import { readFileSync } from 'node:fs'
import { test, expect } from '@playwright/test'
import { buildInventory } from '../../srv/lib/context/inventory.js'
import { parseRecording } from '../../srv/lib/recordings/index.js'
import { mapRecording } from '../../srv/lib/recordings/map.js'
import { generateTourFromRules } from '../../srv/lib/llm/rules.js'
import { lintTour } from '../../srv/lib/validate/lint.js'
import { demoSources } from '../helpers/sources.js'

// Plays tours generated by the rule-based generator in the real demo app: the acceptance test for
// "every target resolved" (Phase 2) - static lint predictions must match what actually happens.

const inventory = buildInventory(demoSources())
const generate = (fixture) => {
  const raw = readFileSync(`test/fixtures/recordings/demo-create-order.${fixture}`, 'utf8')
  const recording = mapRecording(parseRecording(raw), inventory)
  const { tour } = generateTourFromRules({ recording, inventory })
  tour.options.waitTimeoutMs = 800
  return { tour, recording }
}

async function playThrough(page, tour) {
  await page.goto('http://localhost:8081/index.html?ui5=1.120')
  await page.locator('[id="container-demo---main--startTourBtn"]').waitFor()
  await page.evaluate(() => {
    window.__ev = []
    for (const t of ['stepChanged', 'completed', 'error']) {
      window.addEventListener('tourd:' + t, (e) =>
        window.__ev.push({ type: t, index: e.detail.index, code: e.detail.code }),
      )
    }
  })
  await page.evaluate(
    (t) =>
      new Promise((resolve, reject) =>
        sap.ui.require(
          ['tourd/TourPlayer'],
          (P) => P.start(t, {}).then(() => resolve(), reject),
          reject,
        ),
      ),
    tour,
  )
  const shown = []
  for (let i = 0; i < tour.steps.length; i++) {
    await expect(page.locator('.tourd-progress')).toHaveText(
      `Step ${i + 1} of ${tour.steps.length}`,
    )
    shown.push(
      await page.evaluate(() => ({
        title: document.querySelector('.tourd-title').textContent,
        spot: getComputedStyle(document.querySelector('.tourd-spot')).display !== 'none',
      })),
    )
    await page.locator('.tourd-btn--primary').click()
  }
  await expect(page.locator('.tourd-bubble')).toHaveCount(0)
  return { shown, events: await page.evaluate(() => window.__ev) }
}

test('a tour generated from a DevTools recording plays end to end without errors', async ({
  page,
}) => {
  const { tour, recording } = generate('devtools.json')
  expect(lintTour(tour, inventory, { recording }).summary.errors).toBe(0)

  const { shown, events } = await playThrough(page, tour)
  expect(events.filter((e) => e.type === 'error')).toEqual([])
  expect(events.at(-1).type).toBe('completed')
  // every step with a target had a spotlight, the intro was centered
  tour.steps.forEach((step, i) => expect(shown[i].spot, `step ${step.id}`).toBe(!!step.target))
  expect(shown.map((s) => s.title).slice(0, 3)).toEqual([
    'Create an order',
    'Search',
    'Press Create',
  ])
})

test('tours generated from a Test Recorder snippet and from plain text play without errors', async ({
  page,
}) => {
  for (const fixture of ['opa5.js', 'txt']) {
    const { tour, recording } = generate(fixture)
    expect(lintTour(tour, inventory, { recording }).summary.errors).toBe(0)
    const { events } = await playThrough(page, tour)
    expect(
      events.filter((e) => e.type === 'error'),
      fixture,
    ).toEqual([])
    expect(events.at(-1).type).toBe('completed')
  }
})

test('lint predicts exactly the steps the player fails on when navigation is missing', async ({
  page,
}) => {
  const { tour, recording } = generate('opa5.js')
  for (const step of tour.steps) step.before = [] // break the tour on purpose
  const predicted = lintTour(tour, inventory, { recording })
    .issues.filter((i) => i.code === 'step.wrongRoute')
    .map((i) => i.stepId)
  expect(predicted).toEqual(['s2', 's3'])

  const { events } = await playThrough(page, tour)
  const failed = events.filter((e) => e.type === 'error').map((e) => tour.steps[e.index].id)
  expect(failed).toEqual(predicted)
})
